function applyMosaicSDL(component, device, variant, variation='plain') {
 const key=`${component}:${device}:${variant}`;
 const sample=mosaicSDLSamples[`${key}:${variation}`]||mosaicSDLSamples[key];
 const code=document.getElementById('codeSample');
 const link=document.getElementById('mosaicLink');
 if(!code)return;
 code.dataset.format=sample?'sdl':'html';
 code.setAttribute('aria-label',sample?sample.format+' source':'HTML preview code');
 if(sample)code.textContent=sample.code;
 if(link){
  link.hidden=!sample?.url;
  if(sample?.url)link.href=sample.url;
  else link.removeAttribute('href');
 }
}
